CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 VARCHAR(10), c1 TEXT CHECK(c1 IS NULL OR length(c1) < 40), c2 REAL);
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(123456789012, 'iota', 9223372036854775807);
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES('x_y', 559, x'0622965728');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 VARCHAR(10), c1 INT DEFAULT 'd', c2 TEXT NOT NULL DEFAULT 0, c3  COLLATE NOCASE, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(-0.0, 'psi', 1.0e15, 'theta', 6);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(x'', x'7d79a681a6', '42', 'naïve', 6);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(NULL, 123456789012, 'gamma', 'epsilon', NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(x'ba4aa337e688', 427.634, 2.5, 0, NULL);
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', 2, 2), instr('zeta', '-7'), replace('zeta', 'é', '_'), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE '_', 'zeta' GLOB '?', char(78, 451), 'zeta' || '-7', 'zeta' < '-7', 'zeta' = '-7' COLLATE NOCASE;
SELECT length('iota'), upper('iota'), lower('iota'), substr('iota', 4, 4), instr('iota', 'alpha'), replace('iota', 'é', '_'), trim('iota'), ltrim('iota', 'ab'), hex('iota'), quote('iota'), unicode('iota'), 'iota' LIKE '_', 'iota' GLOB 'a*', char(71, 441), 'iota' || 'alpha', 'iota' < 'alpha', 'iota' = 'alpha' COLLATE NOCASE;
SELECT length('eta'), upper('eta'), lower('eta'), substr('eta', 0, 2), instr('eta', '日本'), replace('eta', 'e', ''), trim('eta'), ltrim('eta', 'ab'), hex('eta'), quote('eta'), unicode('eta'), 'eta' LIKE '_', 'eta' GLOB 'a*', char(74, 527), 'eta' || '日本', 'eta' < '日本', 'eta' = '日本' COLLATE NOCASE;
SELECT length('chi'), upper('chi'), lower('chi'), substr('chi', 1, 1), instr('chi', 'Lambda'), replace('chi', 'é', 'XY'), trim('chi'), ltrim('chi', 'ab'), hex('chi'), quote('chi'), unicode('chi'), 'chi' LIKE '%é%', 'chi' GLOB '*', char(68, 778), 'chi' || 'Lambda', 'chi' < 'Lambda', 'chi' = 'Lambda' COLLATE NOCASE;
SELECT id, NOT (ref BETWEEN c0 AND c1 + CAST(x'05b3a4' AS REAL)), nullif(NOT -(ref), c2) FROM t1 ORDER BY id DESC, c0, c1, c2 DESC, c3, ref;
SELECT x'1c1ebcd8', x'6f' BETWEEN typeof(nullif(x'6c0905e473', NULL)) AND '0x1F';
